<script setup lang="ts">
import {computed,onBeforeUnmount,ref,reactive} from 'vue';
const props=defineProps<{data:any;csrf?:string|null}>();
const emit=defineEmits<{published:[any]}>();
const theme=ref(props.data.career_settings.theme),headline=ref(props.data.career_settings.headline),intro=ref(props.data.career_settings.intro);
const editors=ref<number[]>([...props.data.career_editors]),busy=ref(false),message=ref(''),error=ref(''),previewTheme=ref<any>(null),previewDialog=ref<HTMLDialogElement|null>(null);
const tab=ref('themes');
const draft=reactive({...props.data.career_settings});
const groups:Record<string,string[]>={content:['headline','intro','hero_eyebrow','jobs_heading','jobs_intro','application_heading','application_intro','form_heading'],header:['header_brand','header_brand_url','header_label','header_roles_label','header_apply_label','header_show_roles','header_show_apply'],footer:['footer_show','footer_brand','footer_message','footer_copyright','footer_link_label','footer_link_url']};
const tabs=computed(()=>[{id:'themes',name:'Themes'},{id:'content',name:'Page content'},{id:'header',name:'Header'},{id:'footer',name:'Footer'},...(props.data.can_assign_editors?[{id:'access',name:'Access'}]:[])]);
const saveLabel=computed(()=>({themes:'Publish theme',content:'Save page content',header:'Save header',footer:'Save footer',access:'Save access'}[tab.value]||'Save changes'));
function tabKey(event:KeyboardEvent){const keys=['ArrowLeft','ArrowRight','Home','End'];if(!keys.includes(event.key))return;event.preventDefault();const index=tabs.value.findIndex(item=>item.id===tab.value);const next=event.key==='Home'?0:event.key==='End'?tabs.value.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.value.length)%tabs.value.length;tab.value=tabs.value[next].id;requestAnimationFrame(()=>document.getElementById('career-tab-'+tab.value)?.focus());}
const activeTheme=computed(()=>props.data.themes.find((item:any)=>item.id===props.data.career_settings.theme));
let timer:ReturnType<typeof setTimeout>|undefined;
function preview(item:any){previewTheme.value=item;previewDialog.value?.showModal();}
async function publish(){
  busy.value=true;error.value='';message.value='';
  try{
    const body:any={};
    if(tab.value==='themes')body.theme=theme.value;
    else if(tab.value==='access')body.career_editors=editors.value;
    else {for(const key of groups[tab.value]||[])body[key]=key==='headline'?headline.value:key==='intro'?intro.value:draft[key];}
    const response=await fetch('/cv-bank/settings',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':props.csrf||''},body:JSON.stringify(body)});
    const result=await response.json();
    if(!response.ok)throw new Error(Object.values(result.errors||{}).flat().join(' ')||result.message||'Unable to publish careers settings.');
    emit('published',{...result.settings,...(body.career_editors?{career_editors:body.career_editors}:{})});message.value=result.message;
    clearTimeout(timer);timer=setTimeout(()=>{message.value=''},4500);
  }catch(e:any){error.value=e.message;}finally{busy.value=false;}
}
onBeforeUnmount(()=>clearTimeout(timer));
</script>
<template>
  <section class="career-settings">
    <header class="settings-heading"><div><h2>Careers page settings</h2><p>Choose the experience candidates see when they visit your careers page.</p></div></header>
    <div class="published-theme"><span class="published-dot"></span>Published design: <strong>{{activeTheme?.name}}</strong><span>Preview any theme before publishing.</span></div>
    <div class="settings-tabs" role="tablist" aria-label="Careers page settings"><button v-for="item in tabs" :key="item.id" type="button" role="tab" :id="'career-tab-'+item.id" :aria-controls="'career-panel-'+item.id" :aria-selected="tab===item.id" :tabindex="tab===item.id?0:-1" :class="{active:tab===item.id}" @click="tab=item.id;error=''" @keydown="tabKey">{{item.name}}</button></div>
    <form @submit.prevent="publish" novalidate>
      <div v-show="tab==='themes'" id="career-panel-themes" role="tabpanel" aria-labelledby="career-tab-themes">
      <div class="scheme-note"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 3a9 9 0 1 0 0 18V3Z"/><circle cx="12" cy="12" r="9"/></svg><span>Every design follows the visitor's browser: light in light mode, dark in dark mode. Switching color mode keeps the selected layout.</span></div><fieldset class="theme-options"><legend>Choose a layout</legend><div class="theme-grid"><article v-for="item in data.themes" :key="item.id" class="theme-choice" :class="{selected:theme===item.id}">
        <label class="theme-selection"><input type="radio" v-model="theme" :value="item.id" name="career_theme"><span>{{item.name}}</span><span v-if="data.career_settings.theme===item.id" class="live-label">Published</span></label>
        <div class="theme-mini" :class="'mini-'+item.id" :style="{'--mini-accent':item.color,'--mini-bg':item.background}" aria-hidden="true"><div class="mini-nav"><b>Judibas</b><span>Careers &nearr;</span></div>
          <template v-if="item.id==='studio'"><div class="mini-hero"><div><small>YOUR NEXT CHAPTER</small><strong>Good people.<br>Meaningful work.</strong><i></i></div><div class="mini-art"><span></span></div></div><div class="mini-jobs"><i></i><i></i><i></i></div></template>
          <template v-else-if="item.id==='editorial'"><div class="mini-editorial-masthead">Good people.<br><em>Meaningful work.</em></div><div class="mini-editorial-lede"><b>J.</b><i></i><i></i></div><div class="mini-role-index"><span>01 <i></i> &nearr;</span><span>02 <i></i> &nearr;</span></div></template>
          <template v-else-if="item.id==='midnight'"><div class="mini-stage"><small>YOUR NEXT CHAPTER</small><strong>Good people.<br>Meaningful work.</strong><div><i></i><i></i><i></i></div></div><div class="mini-feature-jobs"><i></i><span><i></i><i></i></span></div></template>
          <template v-else-if="item.id==='minimal'"><div class="mini-sidebar-layout"><div><strong>Good<br>people.<br>Good work.</strong><i></i><i></i></div><section><div></div><div></div><div></div><span></span></section></div></template>
          <template v-else-if="item.id==='atlas'"><div class="mini-directory-banner"><strong>Find your next chapter.</strong><span></span></div><div class="mini-directory"><aside><i></i><i></i><i></i></aside><section><i></i><i></i><i></i></section></div></template>
          <template v-else><div class="mini-bento"><div><strong>Good people.<br>Meaningful<br>work.</strong></div><span><b>6</b>OPEN ROLES</span><i>Let's meet &nearr;</i></div><div class="mini-role-index"><span><i></i> +</span><span><i></i> +</span></div></template>
        </div>
        <p>{{item.description}}</p><button type="button" class="button preview-button" @click="preview(item)">Preview design ↗</button>
      </article></div></fieldset></div>
      <section v-show="tab==='content'" id="career-panel-content" role="tabpanel" aria-labelledby="career-tab-content" class="settings-card tab-card"><h3>Page content</h3><p>Edit the introduction, headings and application copy across every theme.</p><label>Eyebrow text<input v-model="draft.hero_eyebrow" required maxlength="500"></label><label>Main headline<input v-model="headline" required maxlength="160"></label><label>Main introduction<textarea v-model="intro" required maxlength="1200" rows="3"></textarea></label><div class="settings-fields"><label>Jobs section heading<input v-model="draft.jobs_heading" required maxlength="500"></label><label>Application form heading<input v-model="draft.form_heading" required maxlength="500"></label></div><label>Jobs section introduction<textarea v-model="draft.jobs_intro" required maxlength="500" rows="2"></textarea></label><label>Application section heading<input v-model="draft.application_heading" required maxlength="500"></label><label>Application section introduction<textarea v-model="draft.application_intro" required maxlength="500" rows="3"></textarea></label></section>
      <section v-show="tab==='header'" id="career-panel-header" role="tabpanel" aria-labelledby="career-tab-header" class="settings-card tab-card"><h3>Header</h3><p>Set the careers page brand and navigation. These changes apply only to the public careers page.</p><div class="settings-fields"><label>Brand name<input v-model="draft.header_brand" required maxlength="500"></label><label>Brand link<input v-model="draft.header_brand_url" required maxlength="500" placeholder="/ or https://example.com"></label></div><label>Header subtitle<input v-model="draft.header_label" required maxlength="500"></label><div class="settings-fields"><label>Open roles link text<input v-model="draft.header_roles_label" required maxlength="500"></label><label>Apply button text<input v-model="draft.header_apply_label" required maxlength="500"></label></div><div class="settings-switches"><label><input type="checkbox" v-model="draft.header_show_roles"><span>Show open roles link<small>Links to current opportunities on the careers page.</small></span></label><label><input type="checkbox" v-model="draft.header_show_apply"><span>Show apply button<small>Links to the CV application form.</small></span></label></div><div class="header-example" aria-label="Header text preview"><strong>{{draft.header_brand}}</strong><span>{{draft.header_label}}</span><div><span v-if="draft.header_show_roles">{{draft.header_roles_label}}</span><span v-if="draft.header_show_apply">{{draft.header_apply_label}} &nearr;</span></div></div></section>
      <section v-show="tab==='footer'" id="career-panel-footer" role="tabpanel" aria-labelledby="career-tab-footer" class="settings-card tab-card"><h3>Footer</h3><p>Customise the closing message, copyright and optional footer link.</p><div class="settings-switches"><label><input type="checkbox" v-model="draft.footer_show"><span>Show footer<small>Display the footer at the bottom of the careers page.</small></span></label></div><label>Footer brand name<input v-model="draft.footer_brand" required maxlength="500"></label><label>Footer message<textarea v-model="draft.footer_message" required maxlength="500" rows="2"></textarea></label><label>Copyright text<input v-model="draft.footer_copyright" required maxlength="500"><small>Use {year} to display the current year automatically.</small></label><div class="settings-fields"><label>Link label (optional)<input v-model="draft.footer_link_label" maxlength="500" placeholder="Privacy policy"></label><label>Link destination (optional)<input v-model="draft.footer_link_url" maxlength="500" placeholder="/privacy or https://example.com/privacy"></label></div><div v-if="draft.footer_show" class="footer-example" aria-label="Footer text preview"><strong>{{draft.footer_brand}}</strong><p>{{draft.footer_message}}</p><span>{{(draft.footer_copyright||'').replaceAll('{year}',String(new Date().getFullYear()))}}</span><span v-if="draft.footer_link_label">{{draft.footer_link_label}}</span></div></section>
      <section v-if="data.can_assign_editors" v-show="tab==='access'" id="career-panel-access" role="tabpanel" aria-labelledby="career-tab-access" class="settings-card tab-card"><h3>Who can manage the careers page?</h3><p>Super Admin and Judibas Admins can manage settings. Grant this permission to HR or another employee with CV Bank access.</p><div v-if="data.eligible_editors.length" class="career-editor-list"><label v-for="person in data.eligible_editors" :key="person.id" class="editor-option"><input type="checkbox" v-model="editors" :value="person.id"><span><strong>{{person.name}}</strong><small>{{person.email}}</small></span><span class="editor-permission">Careers editor</span></label></div><p v-else class="empty-editors">Assign CV Bank product access to employees in Administration → Users to make them available here.</p><small>Careers editors can preview designs, publish a theme and update page text. Only administrators can grant this permission.</small></section>
      <p v-if="error" class="settings-error" role="alert">{{error}}</p><footer class="settings-footer"><p>Save applies changes from this tab only. Your other tabs keep their current settings.</p><button class="button primary" :disabled="busy">{{busy?'Saving...':saveLabel}}</button></footer>
    </form>
    <Teleport to="body"><div v-if="message" class="judibas-toast" role="status"><span class="judibas-toast-dot"></span>{{message}}</div></Teleport>
    <dialog ref="previewDialog" class="theme-preview-dialog" @click="(event)=>{if(event.target===previewDialog)previewDialog?.close()}" @close="previewTheme=null"><template v-if="previewTheme"><header><div><strong>{{previewTheme.name}}</strong><span>Preview — publishing is required to apply this design.</span></div><button type="button" class="theme-preview-close" aria-label="Close theme preview" @click="previewDialog?.close()"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><iframe :src="'/careers?theme='+previewTheme.id" :title="previewTheme.name+' careers page preview'"></iframe><footer><a class="button" :href="'/careers?theme='+previewTheme.id" target="_blank" rel="noopener">Open full preview ↗</a><button type="button" class="button primary" @click="theme=previewTheme.id;previewDialog?.close()">Select this design</button></footer></template></dialog>
  </section>
</template>
<style scoped>
